def check_expression(expression):
    stack = []
    for char in expression:
        if char == '{' or char == '(' or char == '[':
            stack.append(char)
        elif char == '}' or char == ')' or char == ']':
            if not stack:
                return False
            top_char = stack.pop()
            if (char == '}' and top_char != '{') or (char == ')' and top_char != '(') or (char == ']' and top_char != '['):
                return False
    return not stack

